package com.vurka.memoji.util

import android.content.Context
import android.media.AudioAttributes
import android.media.AudioFocusRequest
import android.media.AudioManager
import android.media.MediaPlayer
import android.os.Build
import android.os.Handler
import android.os.Looper
import java.io.File
import java.util.concurrent.Executors

/**
 * Looping ambient music for the four world families.
 *
 * The tracks are generated by [AmbientMusic] on a background thread and cached as WAV files, then
 * played with [MediaPlayer] so long loops do not consume [android.media.SoundPool] memory.
 *
 * Behaviour that matters:
 *  - music only plays while the app is in the foreground;
 *  - audio focus is requested with `USAGE_GAME` / `CONTENT_TYPE_MUSIC`, paused on transient loss
 *    and ducked for short interruptions;
 *  - moving between world families fades the old loop out and the new one in;
 *  - every failure is swallowed: a device that cannot decode or store the audio keeps a playable,
 *    silent game.
 */
object MusicManager {

    private const val CACHE_DIR = "memoji_music_v1"
    private const val MIN_FILE_BYTES = 64 * 1024L
    private const val FADE_IN_MS = 900L
    private const val FADE_OUT_MS = 420L
    private const val FADE_STEP_MS = 40L

    private val handler = Handler(Looper.getMainLooper())
    private val executor = Executors.newSingleThreadExecutor { runnable ->
        Thread(runnable, "MemojiMusic").apply { isDaemon = true }
    }

    private var appContext: Context? = null
    private var audioManager: AudioManager? = null

    // Stored as Any? because AudioFocusRequest does not exist below API 26; a field typed with the
    // new class would be resolved when this class loads on older devices.
    private var focusRequest: Any? = null

    private var player: MediaPlayer? = null
    private var playingGroup: MusicGroup? = null
    private var requestedGroup: MusicGroup? = null

    private var prepareToken = 0
    private var fadeToken = 0
    private var currentGain = 0f

    private var foreground = false
    private var focusGranted = false
    private var released = false

    @Volatile
    private var masterVolume = AudioMix.DEFAULT_MASTER

    @Volatile
    private var musicVolume = AudioMix.DEFAULT_MUSIC

    fun init(context: Context) {
        if (appContext != null) return
        val app = context.applicationContext
        appContext = app
        audioManager = app.getSystemService(Context.AUDIO_SERVICE) as? AudioManager
        released = false
    }

    /** Called from the Activity's `onStart`. */
    fun onEnterForeground() {
        if (released) return
        foreground = true
        val group = requestedGroup ?: return
        if (targetGain() <= AudioMix.SILENCE_THRESHOLD) return
        val mp = player
        if (mp != null && playingGroup == group && focusGranted) {
            try {
                mp.start()
            } catch (_: Throwable) {
                releasePlayer()
                startGroup(group)
                return
            }
            fadePlayerTo(targetGain(), 400L)
        } else {
            startGroup(group)
        }
    }

    /** Called from the Activity's `onStop`: no music may leak into the background. */
    fun onLeaveForeground() {
        foreground = false
        fadeOutAndStop()
    }

    /** Switches to the ambient family for a world. Safe to call on every recomposition. */
    fun setGroup(group: MusicGroup) {
        if (requestedGroup == group) return
        requestedGroup = group
        if (!foreground || released) return
        if (targetGain() <= AudioMix.SILENCE_THRESHOLD) return

        val mp = player
        if (mp != null && playingGroup != null && playingGroup != group) {
            fadePlayerTo(0f, FADE_OUT_MS) {
                releasePlayer()
                if (requestedGroup == group && foreground) startGroup(group)
            }
        } else {
            startGroup(group)
        }
    }

    /** Applies the master/music sliders. Music fades to the new level rather than jumping. */
    fun setVolumes(master: Float, music: Float) {
        masterVolume = master.coerceIn(0f, 1f)
        musicVolume = music.coerceIn(0f, 1f)
        if (!foreground || released) return

        val target = targetGain()
        if (player == null) {
            if (target > AudioMix.SILENCE_THRESHOLD) requestedGroup?.let { startGroup(it) }
            return
        }
        fadePlayerTo(target, 240L)
    }

    /** Frees native resources. The next Activity instance calls [init] again. */
    fun release() {
        released = true
        foreground = false
        prepareToken++
        releasePlayer()
        abandonFocus()
        handler.removeCallbacksAndMessages(null)
        requestedGroup = null
        playingGroup = null
        appContext = null
        audioManager = null
    }

    // ---- Playback --------------------------------------------------------------------------

    private fun targetGain(): Float = AudioMix.gain(masterVolume, musicVolume)

    private fun startGroup(group: MusicGroup) {
        val context = appContext ?: return
        if (!foreground || released) return

        val token = ++prepareToken
        val file = File(File(context.cacheDir, CACHE_DIR), "${group.id}.wav")
        if (file.exists() && file.length() > MIN_FILE_BYTES) {
            prepare(file, group, token)
            return
        }

        executor.execute {
            try {
                val dir = file.parentFile
                if (dir != null && !dir.exists()) dir.mkdirs()
                if (!file.exists() || file.length() <= MIN_FILE_BYTES) {
                    // Render to a temporary file first, so a crash mid-write cannot leave a
                    // truncated WAV that MediaPlayer would try to loop forever.
                    val temp = File(dir ?: context.cacheDir, "${group.id}.tmp")
                    temp.writeBytes(AmbientMusic.renderWav(group))
                    if (!temp.renameTo(file)) {
                        temp.copyTo(file, overwrite = true)
                        temp.delete()
                    }
                }
                handler.post {
                    if (token == prepareToken && foreground && !released) prepare(file, group, token)
                }
            } catch (_: Throwable) {
                // No cache space or no encoder: stay silent rather than break the game.
            }
        }
    }

    private fun prepare(file: File, group: MusicGroup, token: Int) {
        if (token != prepareToken || !foreground || released) return
        releasePlayer()

        val mp = MediaPlayer()
        try {
            mp.setAudioAttributes(
                AudioAttributes.Builder()
                    .setUsage(AudioAttributes.USAGE_GAME)
                    .setContentType(AudioAttributes.CONTENT_TYPE_MUSIC)
                    .build()
            )
            mp.isLooping = true
            mp.setDataSource(file.absolutePath)
            mp.setVolume(0f, 0f)
            mp.setOnPreparedListener {
                if (token != prepareToken || !foreground || released || player !== mp) {
                    safeRelease(mp)
                    return@setOnPreparedListener
                }
                if (!requestFocus()) {
                    releasePlayer()
                    return@setOnPreparedListener
                }
                playingGroup = group
                currentGain = 0f
                try {
                    mp.start()
                } catch (_: Throwable) {
                    releasePlayer()
                    return@setOnPreparedListener
                }
                fadePlayerTo(targetGain(), FADE_IN_MS)
            }
            mp.setOnErrorListener { _, _, _ ->
                releasePlayer()
                true
            }
            player = mp
            currentGain = 0f
            mp.prepareAsync()
        } catch (_: Throwable) {
            safeRelease(mp)
            if (player === mp) player = null
            playingGroup = null
        }
    }

    private fun releasePlayer() {
        fadeToken++
        val mp = player
        player = null
        playingGroup = null
        currentGain = 0f
        if (mp != null) {
            try {
                mp.stop()
            } catch (_: Throwable) {
            }
            safeRelease(mp)
        }
    }

    private fun safeRelease(mp: MediaPlayer) {
        try {
            mp.release()
        } catch (_: Throwable) {
        }
    }

    private fun fadeOutAndStop() {
        val mp = player ?: return
        fadePlayerTo(0f, FADE_OUT_MS) {
            // A new foreground moment or a new group may already have replaced this player.
            if (!foreground && player === mp) releasePlayer()
        }
    }

    /**
     * Steps the volume over [durationMs] on the main thread. A token invalidates in-flight fades
     * when the player is replaced, so two overlapping fades can never fight over the mixer.
     */
    private fun fadePlayerTo(target: Float, durationMs: Long, onEnd: (() -> Unit)? = null) {
        val mp = player
        if (mp == null) {
            onEnd?.invoke()
            return
        }
        val token = ++fadeToken
        val start = currentGain
        val steps = (durationMs / FADE_STEP_MS).toInt().coerceAtLeast(1)
        for (i in 1..steps) {
            handler.postDelayed({
                if (token != fadeToken || player !== mp) return@postDelayed
                val value = start + (target - start) * (i.toFloat() / steps)
                currentGain = value
                try {
                    mp.setVolume(value, value)
                } catch (_: Throwable) {
                }
                if (i == steps) onEnd?.invoke()
            }, i * FADE_STEP_MS)
        }
    }

    // ---- Audio focus -----------------------------------------------------------------------

    private val focusListener = AudioManager.OnAudioFocusChangeListener { change ->
        handler.post { handleFocusChange(change) }
    }

    private fun requestFocus(): Boolean {
        val am = audioManager ?: return false
        if (focusGranted) return true

        val granted = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val request = AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN)
                .setAudioAttributes(
                    AudioAttributes.Builder()
                        .setUsage(AudioAttributes.USAGE_GAME)
                        .setContentType(AudioAttributes.CONTENT_TYPE_MUSIC)
                        .build()
                )
                .setOnAudioFocusChangeListener(focusListener)
                .setWillPauseWhenDucked(false)
                .build()
            focusRequest = request
            am.requestAudioFocus(request) == AudioManager.AUDIOFOCUS_REQUEST_GRANTED
        } else {
            @Suppress("DEPRECATION")
            am.requestAudioFocus(
                focusListener,
                AudioManager.STREAM_MUSIC,
                AudioManager.AUDIOFOCUS_GAIN
            ) == AudioManager.AUDIOFOCUS_REQUEST_GRANTED
        }

        focusGranted = granted
        SoundManager.setAudioFocus(granted)
        return granted
    }

    private fun abandonFocus() {
        val am = audioManager
        if (am != null) {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                (focusRequest as? AudioFocusRequest)?.let { am.abandonAudioFocusRequest(it) }
            } else {
                @Suppress("DEPRECATION")
                am.abandonAudioFocus(focusListener)
            }
        }
        focusRequest = null
        focusGranted = false
        // Effects are not tied to music focus once the app is finishing; leave them enabled.
        SoundManager.setAudioFocus(true)
    }

    private fun handleFocusChange(change: Int) {
        when (change) {
            AudioManager.AUDIOFOCUS_GAIN -> {
                focusGranted = true
                SoundManager.setAudioFocus(true)
                if (!foreground) return
                val mp = player
                if (mp != null) {
                    try {
                        mp.start()
                    } catch (_: Throwable) {
                        return
                    }
                    fadePlayerTo(targetGain(), 400L)
                } else {
                    requestedGroup?.let { startGroup(it) }
                }
            }

            AudioManager.AUDIOFOCUS_LOSS -> {
                focusGranted = false
                SoundManager.setAudioFocus(false)
                fadeOutAndStop()
            }

            AudioManager.AUDIOFOCUS_LOSS_TRANSIENT -> {
                focusGranted = false
                SoundManager.setAudioFocus(false)
                try {
                    player?.pause()
                } catch (_: Throwable) {
                }
            }

            AudioManager.AUDIOFOCUS_LOSS_TRANSIENT_CAN_DUCK -> {
                val ducked = targetGain() * 0.25f
                try {
                    player?.setVolume(ducked, ducked)
                } catch (_: Throwable) {
                }
            }
        }
    }
}
